'use strict';
let TOKEN=location.hash.slice(1)||sessionStorage.getItem('hermesDeskToken')||'';
if(location.hash){sessionStorage.setItem('hermesDeskToken',TOKEN);history.replaceState(null,'',location.pathname)}
let data={},polling=false;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={todo:'시작 대기',ready:'실행 대기',running:'실행 중',in_progress:'실행 중',claimed:'실행 중',blocked:'막힘',done:'완료',archived:'보관'};
const dt=t=>t?new Date(t*1000).toLocaleString('ko-KR'):'기록 없음';
function error(e){$('#error').textContent=e.message||String(e);$('#error').hidden=false}
async function api(path,body){let r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'X-Desk-Token':TOKEN,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok)throw Error(j.error||'요청 실패');return j}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==b.dataset.page);document.querySelectorAll('nav button').forEach(n=>n.classList.toggle('selected',n===b))});
function renderTasks(){let rows=(data.tasks||[]).filter(t=>{let f=$('#taskFilter').value,s=$('#taskSearch').value.toLowerCase();return(f==='all'||(f==='active'?!['done','archived'].includes(t.status):t.status===f))&&`${t.title} ${t.assignee} ${t.id}`.toLowerCase().includes(s)});$('#taskCount').textContent=`${rows.length}개 중 ${Math.min(rows.length,100)}개 표시`;$('#tasks').innerHTML=rows.slice(0,100).map(t=>{let wait=t.parents.filter(p=>!['done','archived'].includes(p.status));return `<details class="task"><summary><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span class="badge ${esc(t.status)}">${esc(names[t.status]||t.status)}</span><span>${esc(t.assignee||'담당 미정')}</span><span>${esc(t.id)}</span>${wait.length?`<span>선행 작업 ${wait.length}개 대기</span>`:''}</div></summary><div class="detail">마지막 이벤트: ${esc(t.lastEvent?.kind||'없음')} · ${dt(t.lastEvent?.created_at)}<br>실행 신호: ${dt(t.last_heartbeat_at)}<br>작업 모델 재정의: ${esc(t.model_override||'없음 · 프로필/세션 설정 사용')}<br>알림 구독: ${t.subscriptions}개 (최종 전달 성공과 별개)${t.block_kind?`<br>차단 종류: ${esc(t.block_kind)}`:''}${wait.length?`<p>먼저 필요한 작업: ${wait.map(p=>`${esc(p.id)} (${esc(names[p.status]||p.status)})`).join(', ')}</p>`:''}${t.last_failure_error?`<p>${esc(t.last_failure_error)}</p>`:''}<h4>최근 실행 결과</h4><pre>${esc(t.result||'저장된 요약이 없습니다.')}</pre></div></details>`}).join('')||'<p class="empty">이 조건에 맞는 작업이 없습니다.</p>';if(rows.length>100)$('#tasks').insertAdjacentHTML('beforeend','<p class="hint">100개씩 표시합니다. 검색으로 범위를 좁혀주세요.</p>')}
const projectNames={councilpm:'AI Council',replypm:'DMmate',hahapm:'하하팩토리',ditalkpm:'디토크',bbqpm:'바베큐국립공원',rewardpm:'리워드드로우',boardpm:'Planning Board',openitpm:'바로열기'};
function agentCard(a){return `<article class="panel"><div class="agent-id">${esc(a.id)}</div><p class="agent-role">${esc(a.role)}</p><details class="agent-extra" data-key="agent-${esc(a.id)}"><summary>상세 · 모델 / 스킬 ${a.skills.length}개${a.brokenSkills?` · 연결 오류 ${a.brokenSkills}`:''}</summary><div class="agent-info">모델: ${esc(a.model)}<br>MCP: ${esc(a.mcp.join(', ')||'명시된 항목 없음')}</div><div class="skill-list">${a.skills.map(esc).join('<br>')||'확인된 스킬 없음'}</div></details></article>`}
function capability(key){
 const c=CAPABILITIES[key],members=(data.agents||[]).filter(a=>key==='aios'?a.group==='AI-OS 관리':a.group===key);
 if(!c&&!members.length)return '';
 const changes=new Map();
 members.forEach(a=>{const baseline=CAPABILITY_BASELINE[a.id]||{};
  (a.skillDetails||[]).forEach(s=>{if(baseline[s.name]!==s.revision)changes.set(s.name,s)});
 });
 const added=[...changes.values()];
 const roles=members.filter(a=>!(a.id in CAPABILITY_BASELINE)).map(a=>`${a.id}: ${a.role==='역할 확인 필요'?'새 담당자 · 역할 설명 확인 필요':a.role}.`);
 const rows=[...(c?.simple||[]),...roles];
 return `<details class="capability" data-key="cap-${esc(key)}"><summary aria-haspopup="dialog"><b>기능</b><span>${rows.length+added.length}개 · 펼쳐보기</span></summary><div class="cap-body"><ol>${rows.map(w=>`<li>${esc(w)}</li>`).join('')}</ol>${added.length?`<div class="auto-functions"><strong>추가·변경된 기능</strong><ul>${added.map(s=>`<li><b>${esc(s.name)}</b><br>${esc(s.description||'설명 없음 · 기능 확인 필요')}</li>`).join('')}</ul></div>`:''}<small class="auto-note">설치 변경 20초마다 반영 · 새 기능은 설치 설명 기준</small></div></details>`
}
