function departmentRoles(group){const agents=(data.agents||[]).filter(a=>a.group===group).sort((a,b)=>Number(b.id.endsWith('pm'))-Number(a.id.endsWith('pm')));return `<section class="role-map"><h3>누구에게 무엇을 맡길까</h3><div class="role-map-grid">${agents.map(a=>`<article><div class="role-map-title"><b>${esc(a.id)}</b><span>${esc(a.role)}</span></div><ul>${(ROLE_FUNCTIONS[a.id]||[a.role==='역할 확인 필요'?'새 담당자 · 역할 확인 필요.':a.role+'.']).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article>`).join('')}</div></section>`}
let focusedCapability=null;
const featureDialog=$('#featureDialog');
function featureSource(){return [...document.querySelectorAll('.capability')].find(e=>e.dataset.key===focusedCapability)}
function updateFeatureDialog(){
 if(!featureDialog.open)return;
 const source=featureSource();
 if(!source){featureDialog.close();return}
 const title=source.closest('.project-node')?.querySelector('.project-top h3')?.textContent||source.closest('.support-department')?.dataset.team||'기능';
 $('#featureTitle').textContent=title;
 $('#featureSubtitle').textContent='기능 · '+source.querySelectorAll('.cap-body ol > li,.auto-functions li').length+'개';
 const team=source.closest('.support-department')?.dataset.team;
 $('#featureContent').innerHTML=(team?departmentRoles(team)+'<h3 class="team-functions-title">함께 맡길 수 있는 기능</h3>':'')+source.querySelector('.cap-body').innerHTML;
}
$('#agentGrid').addEventListener('click',e=>{
 const summary=e.target.closest('.capability > summary'),card=e.target.closest('.team-open');if(!summary&&!card)return;
 e.preventDefault();focusedCapability=card?card.dataset.cap:summary.parentElement.dataset.key;
 featureDialog.showModal();document.body.classList.add('feature-focus');
 updateFeatureDialog();$('#featureContent').scrollTop=0;
});
$('#featureClose').onclick=()=>featureDialog.close();
featureDialog.addEventListener('click',e=>{if(e.target!==featureDialog)return;const r=featureDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)featureDialog.close()});
featureDialog.addEventListener('close',()=>{document.body.classList.remove('feature-focus');const source=featureSource();(source?.closest('.support-department')?.querySelector('.team-open')||source?.querySelector('summary'))?.focus();focusedCapability=null});
function renderAgents(){
 const openKeys=new Set([...document.querySelectorAll('#agentGrid details[data-key][open]')].map(d=>d.dataset.key));
 const query=$('#agentSearch').value.trim().toLowerCase(),group=$('#groupFilter').value;
 const all=data.agents||[],visible=all.filter(a=>(group==='all'||a.group===group)&&`${projectNames[a.id]||''} ${a.id} ${a.group} ${a.role} ${a.skills.join(' ')} ${a.group==='AI-OS 관리'?'기능점검 AI-OS 개발관리':''}`.toLowerCase().includes(query));
 const platform=visible.filter(a=>a.group==='AI-OS 관리'),projects=visible.filter(a=>a.group==='프로젝트'),support=visible.filter(a=>!['AI-OS 관리','프로젝트'].includes(a.group));
 $('#orgCount').textContent=`프로젝트 중심 운영 · ${all.length}개 프로필 · 자동 갱신`;
 const node=(title,body,sub='')=>`<article class="project-node"><div class="project-top"><h3>${esc(title)}</h3>${sub?`<small>${esc(sub)}</small>`:''}</div>${body}</article>`;
 const branch=(title,label,nodes)=>nodes?`<section class="tree-branch branch-${label.toLowerCase()}"><div class="branch-heading"><span>${label}</span><h2>${title}</h2></div><div class="branch-nodes">${nodes}</div></section>`:'';
 const renderProjects=ids=>projects.filter(a=>ids.includes(a.id)).map(a=>node(projectNames[a.id]||a.role,agentCard(a))).join('');
 let checks='';
 if((group==='all'||group==='AI-OS 관리')&&(!query||'모니터링 기능점검'.includes(query)))checks+=node('모니터링',capability('monitor')+`<div class="monitor-node"><p>${esc(data.watchdog||'감시 기록 없음')}</p><small>기존 연결 감시 기록 · 전담 에이전트 연결은 미확인</small></div>`,'AI-OS 기능점검');
 if(platform.length)checks+=node('AI-OS 개발관리',capability('aios')+`<div class="management-agents">${platform.sort((a,b)=>Number(b.id.endsWith('pm'))-Number(a.id.endsWith('pm'))).map(agentCard).join('')}</div>`,'AI-OS 운영·분석·전략 담당');
 const known=['ditalkpm','bbqpm','hahapm','replypm','boardpm','openitpm','rewardpm'];
 let html='<div class="tree-categories">'+branch('기능점검 프로젝트','SYSTEM',checks)+branch('팀 프로젝트','TEAM',renderProjects(['ditalkpm','bbqpm','hahapm','replypm']))+branch('개인 프로젝트','PERSONAL',renderProjects(['boardpm','openitpm','rewardpm']))+branch('공통 협업 · 기타','COLLABORATION',projects.filter(a=>!known.includes(a.id)).map(a=>node(projectNames[a.id]||a.role,agentCard(a))).join(''));
 if(support.length){const groups=[...new Set(support.map(a=>a.group))];html+=branch('프로젝트 지원 부서','SUPPORT',groups.map(g=>{const members=support.filter(a=>a.group===g);return `<article class="project-node support-department" data-team="${esc(g)}"><button class="team-open" data-cap="cap-${esc(g)}" aria-haspopup="dialog"><b>${esc(g)}</b><span>${members.length}명 · 역할 / 기능</span></button><div hidden>${capability(g)}</div></article>`}).join(''))}
 html+='</div>';
 $('#agentGrid').innerHTML=visible.length||checks?html:'<p class="empty">조건에 맞는 프로필이 없습니다.</p>';
 document.querySelectorAll('#agentGrid details[data-key]').forEach(d=>{if(openKeys.has(d.dataset.key)&&!d.classList.contains('capability'))d.open=true});
 updateFeatureDialog();
}
async function refresh(){try{const selected=$('#profile').value;data=await api('status');$('#error').hidden=true;if(data.errors?.length)error(Error(data.errors.join(' / ')));$('#clock').textContent=`현황 확인 ${dt(data.checked)} · 20초마다 갱신`;let c=data.counts||{};$('#stats').innerHTML=[['실행 중',(c.running||0)+(c.in_progress||0)+(c.claimed||0)],['시작·실행 대기',(c.todo||0)+(c.ready||0)],['막힌 작업',c.blocked||0],['완료',c.done||0],['설치된 프로필',(data.agents||[]).length]].map(([n,v],i)=>`<div class="stat"><span>${n}</span><b>${(i===4?!data.agents:(!data.counts||data.missing))?'—':v}</b></div>`).join('');$('#primaryModel').textContent=data.model?.default||'설정 읽기 실패';$('#provider').textContent=data.model?.provider||'';$('#fallbacks').innerHTML=(data.fallbacks||[]).map((x,i)=>`<p>${i+1}차 예비 · ${esc(x.model)}<br><small>${esc(x.provider)}</small></p>`).join('');$('#modelChecks').innerHTML=(data.modelChecks||[]).map(x=>`<p>${esc(x.model)} · ${x.ok?'호출 검증 성공':'호출 검증 실패'}<br><small>${esc(dt(x.checked))} · ${x.observed?.some(e=>e.event==='post_tool_call'&&e.status==='ok')?'도구 실행 포함':'짧은 응답 시험'}</small></p>`).join('');$('#health').textContent=(data.watchdog||'기록 없음')+(data.watchdogAge>300?' · 최근 기록이 오래됐습니다.':'');$('#profile').innerHTML=(data.agents||[]).map(a=>`<option value="${esc(a.id)}">${esc(a.group)} / ${esc(a.id)}</option>`).join('');$('#profile').value=(data.agents||[]).some(a=>a.id===selected)?selected:'default';const old=$('#groupFilter').value;$('#groupFilter').innerHTML='<option value="all">프로젝트 · 전체 조직</option>'+[...new Set((data.agents||[]).map(a=>a.group))].map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('');$('#groupFilter').value=[...$('#groupFilter').options].some(o=>o.value===old)?old:'all';renderTasks();renderAgents()}catch(e){error(e)}}
function terminalView(t){$('#send').disabled=t.running;$('#profile').disabled=t.running;$('#interrupt').disabled=!t.running;$('#reply').disabled=!t.running;$('#runState').textContent=t.running?'실행 중 · 질문 대기일 수도 있음':t.finished?'실행 종료':'대기';$('#exitState').textContent=t.running?`${t.profile} · ${dt(t.started)}`:t.finished?`종료 코드 ${t.exitcode} · ${dt(t.finished)}`:'아직 실행하지 않았습니다';let p=$('#output'),near=p.scrollHeight-p.scrollTop-p.clientHeight<80;p.textContent=t.output||'보낸 명령의 실행 기록과 응답이 여기에 나타납니다.';if(near)p.scrollTop=p.scrollHeight}
async function poll(){if(polling)return;polling=true;try{terminalView(await api('terminal'))}catch(e){error(e)}finally{polling=false}}
$('#send').onclick=async()=>{try{const prompt=$('#prompt').value;if(!prompt.trim())return;$('#send').disabled=true;terminalView(await api('start',{profile:$('#profile').value,prompt}));$('#prompt').value=''}catch(e){error(e);$('#send').disabled=false}};
$('#reply').onclick=async()=>{try{terminalView(await api('reply',{text:$('#replyText').value}));$('#replyText').value=''}catch(e){error(e)}};
$('#interrupt').onclick=async()=>{try{terminalView(await api('interrupt',{}))}catch(e){error(e)}};
$('#refresh').onclick=refresh;$('#taskSearch').oninput=renderTasks;$('#taskFilter').onchange=renderTasks;$('#agentSearch').oninput=renderAgents;$('#groupFilter').onchange=renderAgents;
async function connect(){try{const r=await fetch('/api/connect',{headers:{'X-Desk-Bootstrap':'1'}});if(!r.ok)throw Error('로컬 연결을 확인할 수 없습니다. 화면을 새로고침해주세요.');TOKEN=(await r.json()).token;sessionStorage.setItem('hermesDeskToken',TOKEN);await refresh();await poll();setInterval(refresh,20000);setInterval(poll,1500)}catch(e){error(e)}}
connect();

// Pointer-driven spatial cards. Delegation survives live directory refreshes.
(()=>{
 const motion=matchMedia('(hover:hover) and (pointer:fine) and (prefers-reduced-motion:no-preference)');
 let active=null,frame=0,point=null,bounds=null;
 function clear(){if(frame)cancelAnimationFrame(frame);frame=0;if(active){active.classList.remove('spatial-active');for(const k of ['--rx','--ry','--light-x','--light-y','--shadow-x','--shadow-y'])active.style.removeProperty(k);active.closest('.tree-branch')?.classList.remove('spatial-branch')}active=null;bounds=null}
 document.addEventListener('pointermove',e=>{
  if(!motion.matches||e.pointerType==='touch')return;
  const card=e.target.closest('#agentGrid .project-node,.org-root,#featureContent .role-map-grid article');
  if(card!==active){clear();if(card){active=card;bounds=card.getBoundingClientRect();card.classList.add('spatial-active');card.closest('.tree-branch')?.classList.add('spatial-branch')}}
  if(!active)return;point={x:e.clientX,y:e.clientY};if(frame)return;
  frame=requestAnimationFrame(()=>{frame=0;if(!active?.isConnected){clear();return}const x=Math.max(0,Math.min(1,(point.x-bounds.left)/bounds.width)),y=Math.max(0,Math.min(1,(point.y-bounds.top)/bounds.height));active.style.setProperty('--rx',`${(0.5-y)*12}deg`);active.style.setProperty('--ry',`${(x-0.5)*18}deg`);active.style.setProperty('--light-x',`${x*100}%`);active.style.setProperty('--light-y',`${y*100}%`);active.style.setProperty('--shadow-x',`${(0.5-x)*30}px`);active.style.setProperty('--shadow-y',`${24+(1-y)*18}px`)});
 },{passive:true});
 document.addEventListener('pointerleave',clear);document.addEventListener('scroll',clear,true);window.addEventListener('blur',clear);motion.addEventListener('change',clear);
})();
